    for(int i=0;i<*n;++i)if(!strcmp((*vars)[i].name,name)) {
        (*vars)[i].value=v;
        return;
    }
    *vars=resize(*vars,(size_t)(*n+1)*sizeof **vars);
    strcpy((*vars)[*n].name,name);
    (*vars)[(*n)++].value=v;
